def is_multiply_prime(a):
    def is_prime(n):
      if n <= 1:
        return False
      for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
          return False
      return True
    count = 0
    for i in range(2, int(a**0.5) + 1):
      if is_prime(i):
        for j in range(2, int(a/i) + 1):
          if is_prime(j) and i * j * (a / (i * j)) == a:
            count += 1
    return count >= 3 
